/**
 * DeleteTenantModal — soft-delete confirm. Phase 4f.
 *
 * Soft-delete (status → suspended) is reversible, so we use a single
 * confirm button rather than the typed-confirmation flow from the
 * destructive-modal spec. Hard delete (when it ships) will need the
 * full typed pattern.
 *
 * Phase 3 (radix-ui): migrated from the admin `Modal` (role="dialog") to
 * the shared `@omnicore-platform/ui` AlertDialog (role="alertdialog") so the
 * destructive confirm carries the correct alertdialog semantics — an explicit
 * Cancel plus a destructive Action. The destructive Action keeps its cog-danger
 * styling (text label, never color-alone) and its async onClick; we suppress
 * Radix's auto-close on Action so the async delete flow owns when the dialog
 * closes (on success) or stays open to surface an inline error. The title /
 * eyebrow / blocked-state copy now use the `m.tenants_*` catalog keys (added on
 * main) so i18n behavior is unchanged by the migration.
 */

import {
  useCallback,
  useEffect,
  useState,
  type ReactElement,
} from "react";
import { AlertDialog } from "@omnicore-platform/ui";
import {
  deleteTenant,
  type AdminTenant,
} from "../api/tenants";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { useLocale } from "@omnicore-platform/platform-chrome";

export interface DeleteTenantModalProps {
  open: boolean;
  tenant: AdminTenant;
  onClose: () => void;
  /** Fired with the post-image (status=suspended) after a successful
   *  soft-delete so the parent can swap its cached row + refresh the
   *  table without a refetch round-trip. */
  onDeleted: (updated: AdminTenant) => void;
  /** Phase 4h. Names of active child workspaces under this tenant.
   *  When non-empty, the modal renders a blocked-state — no delete
   *  button is shown; the admin is told to suspend/remove the children
   *  first. Children of a leaf workspace (none expected) collapse to
   *  the normal confirm flow. */
  childWorkspaceNames?: readonly string[];
}

type State =
  | { phase: "idle" }
  | { phase: "deleting" }
  | { phase: "error"; message: string };

export function DeleteTenantModal({
  open,
  tenant,
  onClose,
  onDeleted,
  childWorkspaceNames,
}: DeleteTenantModalProps): ReactElement {
  useLocale();
  const [state, setState] = useState<State>({ phase: "idle" });
  const blocked = (childWorkspaceNames ?? []).length > 0;

  useEffect(() => {
    if (open) setState({ phase: "idle" });
  }, [open]);

  const handleDelete = useCallback(async (): Promise<void> => {
    if (blocked) return;
    if (state.phase === "deleting") return;
    setState({ phase: "deleting" });
    try {
      const updated = await deleteTenant(tenant.id);
      onDeleted(updated);
      onClose();
    } catch (err: unknown) {
      setState({
        phase: "error",
        message: err instanceof Error ? err.message : "Delete failed",
      });
    }
  }, [blocked, state.phase, tenant.id, onDeleted, onClose]);

  return (
    <AlertDialog.Root
      open={open}
      onOpenChange={(next) => {
        if (!next) onClose();
      }}
    >
      <AlertDialog.Content
        data-testid="modal-panel"
        className="flex max-h-cog-vh-inset-120 w-cog-modal max-w-cog-vw-inset-32 flex-col overflow-hidden rounded-base border border-cog-divider bg-cog-surface shadow-cog-overlay"
      >
        <div className="flex shrink-0 items-center justify-between border-b border-cog-divider px-cog-5 py-cog-4">
          <div className="flex flex-col gap-cog-1">
            <span className="text-eyebrow uppercase tracking-cog-eyebrow font-bold text-cog-text-tertiary">
              {m.tenants_delete_confirm_eyebrow()}
            </span>
            <AlertDialog.Title className="text-heading-sm font-semibold text-cog-text-primary">
              {blocked
                ? m.tenants_suspend_org_first_title()
                : m.tenants_delete_workspace_question_title()}
            </AlertDialog.Title>
          </div>
        </div>

        <AlertDialog.Description asChild>
          <div
            data-testid="delete-tenant-body"
            className="flex flex-1 flex-col gap-cog-3 overflow-y-auto px-cog-5 py-cog-4 text-body-sm text-cog-text-primary"
          >
            {blocked ? (
              <>
                <span>
                  <span className="font-semibold">{tenant.name}</span>{" "}
                  {m.tenants_still_has()}{" "}
                  {childWorkspaceNames!.length}{" "}
                  {m.tenants_active_workspace()}
                  {childWorkspaceNames!.length === 1 ? "" : "s"}.{" "}
                  {m.tenants_suspend_or_remove_children()}
                </span>
                <ul
                  data-testid="delete-tenant-blocked-children"
                  className="ms-cog-4 list-disc text-body-sm text-cog-text-secondary"
                >
                  {childWorkspaceNames!.map((n) => (
                    <li key={n}>{n}</li>
                  ))}
                </ul>
              </>
            ) : (
              <>
                <span>
                  {m.tenants_suspending_prefix()}
                  <span className="font-semibold">{tenant.name}</span>
                  {m.tenants_blocks_login_note()}
                </span>
                <ul className="ms-cog-4 list-disc text-body-sm text-cog-text-secondary">
                  <li>{m.tenants_users_cannot_sign_in()}</li>
                  <li>{m.tenants_audit_chain_note()}</li>
                  <li>{m.tenants_restore_from_timeline()}</li>
                </ul>
              </>
            )}

            {state.phase === "error" && (
              <span
                role="alert"
                data-testid="delete-tenant-error"
                className="rounded-base border border-cog-danger-200 bg-cog-danger-50 px-cog-3 py-cog-2 text-body-sm text-cog-danger-600 dark:border-cog-danger-800 dark:bg-cog-danger-950 dark:text-cog-danger-dark"
              >
                {state.message}
              </span>
            )}
          </div>
        </AlertDialog.Description>

        <div className="flex shrink-0 items-center justify-end gap-cog-2 border-t border-cog-divider px-cog-5 py-cog-3">
          <AlertDialog.Cancel
            className="
              inline-flex h-cog-6-5 items-center rounded-base border border-cog-divider
              bg-cog-surface px-cog-3 text-body-sm font-semibold text-cog-text-primary
              transition-colors duration-standard
              hover:border-cog-border hover:bg-cog-surface-muted
              focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-1
            "
          >
            {blocked
              ? m.tenants_delete_close_btn()
              : m.tenants_cancel_btn()}
          </AlertDialog.Cancel>
          {!blocked && (
            <AlertDialog.Action
              onClick={(event) => {
                // Suppress Radix's auto-close so the async delete flow owns
                // closing: close on success (via onClose), stay open on error.
                event.preventDefault();
                void handleDelete();
              }}
              disabled={state.phase === "deleting"}
              data-testid="delete-tenant-confirm"
              className="
                inline-flex h-cog-6-5 items-center rounded-base
                border border-cog-danger-600 bg-cog-danger-600 px-cog-3
                text-body-sm font-semibold text-white
                transition-colors duration-standard
                hover:border-cog-danger-600 hover:bg-cog-danger-600
                focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-1
                disabled:cursor-not-allowed disabled:opacity-50
              "
            >
              {state.phase === "deleting"
                ? m.tenants_delete_deleting_btn()
                : m.tenants_delete_workspace_btn()}
            </AlertDialog.Action>
          )}
        </div>
      </AlertDialog.Content>
    </AlertDialog.Root>
  );
}


