/**
 * TenantsTable — admin board §04.
 *
 * Phase 4a: live read of workspaces.
 * Phase 4d: member-count column.
 * Phase 4e: owner column with batched identity-svc lookups.
 * Phase 4f: status column, trial-period support, modal-based
 *           Create / Edit / Delete (files-mfe Modal pattern).
 * Phase 4h: parent/child grouping. Organizations (parent_id == null)
 *           sort alphabetically; each org's child workspaces sort
 *           alphabetically beneath their parent with a left indent.
 *           Trailing actions column (kebab) opens row Edit / Delete.
 *
 * Columns (left → right):
 *   Workspace (name + monospace slug, indented when child)
 *   Owner     (creator's display name, em-dash for system-created)
 *   Status    (Active / Trial+days / Past due / Suspended)
 *   Members   (tabular-nums count from org-svc join)
 *   Created   (relative time from created_at)
 *   Updated   (relative time from updated_at)
 *   ⋯         (row actions kebab — Phase 4h)
 *
 * Loading / empty / error states render inline so the route shell
 * doesn't have to special-case them.
 */

import { useEffect, useMemo, useState, type ReactElement } from "react";
import { CornerDownRight } from "@omnicore-platform/ui/icons";
import {
  listTenants,
  type AdminTenant,
  type ListTenantsResult,
} from "../api/tenants";
import { tenantStatusPillFor } from "./TenantStatusPill";
import { TenantRowMenu } from "./TenantRowMenu";
import { orderTreeRows } from "./tenantTree";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { useLocale } from "@omnicore-platform/platform-chrome";

export interface TenantsTableProps {
  /** Page size. Defaults to 50. */
  pageSize?: number;
  /** Bump to force a refetch. */
  reloadKey?: number;
  /** Fired when a row is clicked. Parent opens the detail drawer. */
  onSelectTenant?: (tenant: AdminTenant) => void;
  /** id of the currently-selected tenant; row gets aria-current=true. */
  selectedTenantId?: string | null;
  /** Phase 4h. Fired when the row's kebab → Edit is chosen. */
  onEditTenant?: (tenant: AdminTenant) => void;
  /** Phase 4h. Fired when the row's kebab → Delete is chosen. The
   *  parent owns confirm-modal state and the child-count check (orgs
   *  with active children are blocked). */
  onDeleteTenant?: (tenant: AdminTenant) => void;
}

type TableState =
  | { phase: "loading" }
  | { phase: "error"; message: string }
  | { phase: "ready"; tenants: AdminTenant[]; nextPageToken: string };

/** Format an RFC-3339 timestamp as "2d", "5h", "1mo", etc. */
function relative(now: Date, isoDate: string): string {
  if (!isoDate) return "—";
  const then = new Date(isoDate).getTime();
  if (Number.isNaN(then)) return "—";
  const deltaSec = Math.max(0, Math.round((now.getTime() - then) / 1000));
  if (deltaSec < 60) return `${deltaSec}s`;
  const m = Math.round(deltaSec / 60);
  if (m < 60) return `${m}m`;
  const h = Math.round(m / 60);
  if (h < 24) return `${h}h`;
  const d = Math.round(h / 24);
  if (d < 30) return `${d}d`;
  const mo = Math.round(d / 30);
  if (mo < 12) return `${mo}mo`;
  const y = Math.round(mo / 12);
  return `${y}y`;
}

/** Render the owner cell. Prefers display_name; falls back to email,
 *  then a shortened uuid (first 8 chars) so admins still have a hint
 *  when identity-svc couldn't resolve the user. System-created
 *  (no owner) renders as an em-dash. */
function ownerLabel(owner: AdminTenant["owner"]): string {
  if (!owner) return "—";
  if (owner.display_name) return owner.display_name;
  if (owner.email) return owner.email;
  return owner.user_id.slice(0, 8);
}


export function TenantsTable({
  pageSize = 50,
  reloadKey = 0,
  onSelectTenant,
  selectedTenantId,
  onEditTenant,
  onDeleteTenant,
}: TenantsTableProps): ReactElement {
  useLocale();
  const [state, setState] = useState<TableState>({ phase: "loading" });
  const now = useMemo(() => new Date(), []);

  useEffect(() => {
    let cancelled = false;
    setState({ phase: "loading" });
    listTenants({ page_size: pageSize })
      .then((res: ListTenantsResult) => {
        if (cancelled) return;
        setState({
          phase: "ready",
          tenants: res.tenants,
          nextPageToken: res.next_page_token,
        });
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setState({
          phase: "error",
          message: err instanceof Error ? err.message : "Failed to load tenants",
        });
      });
    return () => {
      cancelled = true;
    };
  }, [pageSize, reloadKey]);

  const rows = useMemo(
    () => (state.phase === "ready" ? orderTreeRows(state.tenants) : []),
    [state],
  );

  if (state.phase === "loading") {
    return (
      <div
        role="status"
        aria-live="polite"
        data-testid="tenants-table-loading"
        className="rounded-lg border border-cog-divider bg-cog-surface p-cog-6 text-body-sm text-cog-text-tertiary"
      >
        {m.tenants_loading_workspaces()}
      </div>
    );
  }

  if (state.phase === "error") {
    return (
      <div
        role="alert"
        data-testid="tenants-table-error"
        className="rounded-lg border border-cog-danger-200 bg-cog-danger-50 p-cog-4 text-body-sm text-cog-danger-600 dark:border-cog-danger-800 dark:bg-cog-danger-950 dark:text-cog-danger-dark"
      >
        {state.message}
      </div>
    );
  }

  if (state.tenants.length === 0) {
    return (
      <div
        data-testid="tenants-table-empty"
        className="flex flex-col items-start gap-cog-2 rounded-lg border border-cog-divider bg-cog-surface p-cog-6"
      >
        <span className="text-eyebrow uppercase tracking-cog-eyebrow font-bold text-cog-text-tertiary">
          {m.tenants_no_workspaces_title()}
        </span>
        <p className="max-w-md text-body-sm text-cog-text-secondary">
          {m.tenants_no_workspaces_body()}
        </p>
      </div>
    );
  }

  return (
    <div
      data-testid="tenants-table"
      className="overflow-hidden rounded-lg border border-cog-divider bg-cog-surface"
    >
      <table className="w-full border-collapse text-body-sm">
        <thead>
          <tr className="border-b border-cog-divider">
            <th
              scope="col"
              className="px-cog-4 py-cog-2 text-left text-eyebrow uppercase tracking-cog-eyebrow font-bold text-cog-text-tertiary"
            >
              {m.tenants_workspace_col_header()}
            </th>
            <th
              scope="col"
              className="px-cog-4 py-cog-2 text-left text-eyebrow uppercase tracking-cog-eyebrow font-bold text-cog-text-tertiary"
            >
              {m.tenants_owner_col_header()}
            </th>
            <th
              scope="col"
              className="px-cog-4 py-cog-2 text-left text-eyebrow uppercase tracking-cog-eyebrow font-bold text-cog-text-tertiary"
            >
              {m.tenants_status_col_header()}
            </th>
            <th
              scope="col"
              className="px-cog-4 py-cog-2 text-right text-eyebrow uppercase tracking-cog-eyebrow font-bold text-cog-text-tertiary"
            >
              {m.tenants_members_col_header()}
            </th>
            <th
              scope="col"
              className="px-cog-4 py-cog-2 text-right text-eyebrow uppercase tracking-cog-eyebrow font-bold text-cog-text-tertiary"
            >
              {m.tenants_created_col_header()}
            </th>
            <th
              scope="col"
              className="px-cog-4 py-cog-2 text-right text-eyebrow uppercase tracking-cog-eyebrow font-bold text-cog-text-tertiary"
            >
              {m.tenants_updated_col_header()}
            </th>
            <th
              scope="col"
              className="px-cog-2 py-cog-2 text-right text-eyebrow uppercase tracking-cog-eyebrow font-bold text-cog-text-tertiary"
            >
              <span className="sr-only">{m.tenants_actions_col_header()}</span>
            </th>
          </tr>
        </thead>
        <tbody>
          {rows.map(({ tenant: t, depth }) => {
            const selected = selectedTenantId === t.id;
            const clickable = onSelectTenant !== undefined;
            // Phase 4i: org-ness is determined by parent_id, not by
            // visual depth. Orphan rows (parent_id set but the parent
            // is outside the visible set) render at depth 0 too but
            // still inherit from their parent and shouldn't show a
            // status pill.
            const isOrg = !t.parent_id;
            return (
              <tr
                key={t.id}
                role={clickable ? "button" : undefined}
                aria-current={selected ? "true" : undefined}
                aria-level={depth + 1}
                tabIndex={clickable ? 0 : undefined}
                data-testid={`tenants-row-${t.id}`}
                data-depth={depth}
                onClick={clickable ? () => onSelectTenant(t) : undefined}
                onKeyDown={
                  clickable
                    ? (e) => {
                        if (e.key === "Enter" || e.key === " ") {
                          e.preventDefault();
                          onSelectTenant(t);
