/**
 * CreateTenantModal — admin board §04 (Phase 4f rebuild).
 *
 * Drops the hand-rolled portal in favor of the shared Modal component
 * ported from files-mfe so all admin Create / Edit / Delete
 * surfaces share their focus-trap + scroll-lock behaviors.
 *
 * Fields:
 *   - Display name (required, auto-suggests slug)
 *   - Slug (required, URL-safe; auto-suggested until user types)
 *   - Trial period: None / 30 / 90 / 180 days (org-only)
 *
 * Title flips by context: "Create organization" at the top-level Tenants
 * page, "Create a workspace" when opened with a preset parentId from an
 * org's Workspaces tab.
 *
 * Dry run button validates without writing; the preview banner shows
 * the projected tenant. Submit closes on success.
 */

import {
  useCallback,
  useEffect,
  useState,
  type FormEvent,
  type ReactElement,
} from "react";
import { z } from "zod";
import {
  displayNameSchema,
  slugSchema,
  optionalUuidSchema,
  fieldErrorsFromZod,
  useFieldErrors,
  type FieldErrors,
} from "@omnicore-platform/platform-chrome";
import { Modal } from "../components/Modal";
import {
  createTenant,
  type AdminTenant,
  type CreateTenantResult,
} from "../api/tenants";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { useLocale, type TranslatedString } from "@omnicore-platform/platform-chrome";

const baseSchema = z.object({
  name: displayNameSchema,
  slug: slugSchema,
  parent_id: optionalUuidSchema,
});

export interface CreateTenantModalProps {
  open: boolean;
  onCreated: (tenant: AdminTenant) => void;
  onClose: () => void;
  /** Phase 4h. When set, the parent input is hidden and the new
   *  tenant is created as a child of this org. Used by the
   *  org-detail Workspaces tab so admins can't accidentally create
   *  a sub-workspace under the wrong parent. */
  parentId?: string;
}

type SubmitState =
  | { phase: "idle" }
  | { phase: "submitting" }
  | { phase: "preview"; result: CreateTenantResult }
  | { phase: "error"; message: string };

/** Trial period options surfaced in the modal. None == 0 == no trial. */
function buildTrialOptions(): readonly { label: string; value: number }[] {
  return [
    { label: m.tenants_trial_none(), value: 0 },
    { label: m.tenants_trial_30(), value: 30 },
    { label: m.tenants_trial_90(), value: 90 },
    { label: m.tenants_trial_180(), value: 180 },
  ];
}

function slugify(input: string): string {
  return input
    .toLowerCase()
    .trim()
    .replace(/\s+/g, "-")
    .replace(/[^a-z0-9-]/g, "")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "");
}

export function CreateTenantModal({
  open,
  onCreated,
  onClose,
  parentId: presetParentId,
}: CreateTenantModalProps): ReactElement {
  const [name, setName] = useState("");
  const [slug, setSlug] = useState("");
  const [slugTouched, setSlugTouched] = useState(false);
  const [parentId, setParentId] = useState("");
  const [trialDays, setTrialDays] = useState<number>(0);
  const [submit, setSubmit] = useState<SubmitState>({ phase: "idle" });
  const parentLocked = presetParentId !== undefined && presetParentId !== "";
  const { errors, setErrors, clear } = useFieldErrors();

  // Reset on re-open so reopening from "Created" doesn't show stale state.
  useEffect(() => {
    if (!open) return;
    setName("");
    setSlug("");
    setSlugTouched(false);
    setParentId(presetParentId ?? "");
    setTrialDays(0);
    setSubmit({ phase: "idle" });
    clear();
  }, [open, presetParentId, clear]);

  const handleNameChange = useCallback(
    (next: string) => {
      setName(next);
      if (!slugTouched) {
        setSlug(slugify(next));
      }
    },
    [slugTouched],
  );

  const handleSlugChange = useCallback((next: string) => {
    setSlug(next);
    setSlugTouched(true);
  }, []);

  const parseResult = baseSchema.safeParse({
    name: name.trim(),
    slug: slug.trim(),
    parent_id: parentId.trim(),
  });
  const canSubmit = parseResult.success && submit.phase !== "submitting";

  function validateField(field: "name" | "slug" | "parent_id"): void {
    const result = baseSchema.safeParse({
      name: name.trim(),
      slug: slug.trim(),
      parent_id: parentId.trim(),
    });
    if (!result.success) {
      const fieldErrors = fieldErrorsFromZod(result.error);
      if (fieldErrors[field] !== undefined) {
        setErrors((prev: FieldErrors) => ({ ...prev, [field]: fieldErrors[field] }));
      } else {
        clear(field);
      }
    } else {
      clear(field);
    }
  }

  async function runCreate(dryRun: boolean): Promise<void> {
    if (!canSubmit) return;
    setSubmit({ phase: "submitting" });
    try {
      const params: {
        name: string;
        slug: string;
        parent_id?: string;
        dry_run?: boolean;
        trial_days?: number;
      } = { name, slug };
      if (parentId.trim() !== "") params.parent_id = parentId.trim();
      if (dryRun) params.dry_run = true;
      // trial_days is org-only — never send it when creating a workspace
      // (parentLocked is true when the modal opened from an org's
      // Workspaces tab). Belt-and-suspenders with the hidden Field above.
      if (!parentLocked && trialDays > 0) params.trial_days = trialDays;
      const result = await createTenant(params);
      if (result.dry_run_planned) {
        setSubmit({ phase: "preview", result });
        return;
      }
      onCreated(result.tenant);
      onClose();
    } catch (err: unknown) {
      setSubmit({
        phase: "error",
        message: err instanceof Error ? err.message : "Create failed",
      });
    }
  }

  async function handleSave(e: FormEvent<HTMLFormElement>): Promise<void> {
    e.preventDefault();
    await runCreate(false);
  }

  const trialOptions = buildTrialOptions();
  const footer = (
    <>
      <button
        type="button"
        onClick={() => runCreate(true)}
        disabled={!canSubmit}
        data-testid="create-tenant-dry-run"
        className="
          inline-flex h-cog-6-5 items-center rounded-base border border-cog-divider
          bg-cog-surface px-cog-3 text-body-sm font-semibold text-cog-text-primary
          transition-colors duration-standard
          hover:border-cog-border hover:bg-cog-surface-muted
          focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-1
          disabled:cursor-not-allowed disabled:opacity-50
          mr-auto
        "
      >
        {m.tenants_dry_run_btn()}
      </button>
      <button
        type="button"
        onClick={onClose}
        className="
          inline-flex h-cog-6-5 items-center rounded-base border border-cog-divider
          bg-cog-surface px-cog-3 text-body-sm font-semibold text-cog-text-primary
          transition-colors duration-standard
          hover:border-cog-border hover:bg-cog-surface-muted
          focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-1
        "
      >
        {m.tenants_cancel_btn()}
      </button>
      <button
        type="submit"
        form="create-tenant-form"
        disabled={!canSubmit}
        data-testid="create-tenant-submit"
        className="
          inline-flex h-cog-6-5 items-center rounded-base
          border border-cog-blue-600 bg-cog-blue-600 px-cog-3
          text-body-sm font-semibold text-white
          transition-colors duration-standard
          hover:border-cog-blue-700 hover:bg-cog-blue-700
          focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-1
          disabled:cursor-not-allowed disabled:opacity-50
          dark:border-cog-blue-700 dark:bg-cog-blue-700 dark:text-white
        "
      >
        {submit.phase === "submitting" ? m.tenants_creating_btn() : m.tenants_create_btn()}
      </button>
    </>
  );

  return (
    <Modal
      title={parentLocked ? m.tenants_create_workspace_title() : m.tenants_create_organization_title()}
      eyebrow={parentLocked ? m.tenants_create_workspace_eyebrow() : m.tenants_create_organization_eyebrow()}
      open={open}
      onClose={onClose}
      footer={footer}
    >
      <form
        id="create-tenant-form"
        onSubmit={handleSave}
        data-testid="create-tenant-form"
        className="flex flex-col gap-cog-4"
      >
        <Field
          label={m.tenants_display_name_label()}
          input={
            <input
              type="text"
              value={name}
              onChange={(e) => handleNameChange(e.target.value)}
              onBlur={() => validateField("name")}
              aria-label={m.tenants_display_name_label()}
              aria-invalid={Boolean(errors.name)}
              data-testid="create-tenant-name"
              className="
                w-full rounded-base border border-cog-divider
                bg-cog-surface px-cog-2 py-cog-2
                text-body-sm text-cog-text-primary
                focus:border-cog-blue-600 focus:outline-none
              "
            />
          }
          error={errors.name}
        />

        <Field
          label={m.tenants_slug_label()}
          input={
            <input
              type="text"
              value={slug}
              onChange={(e) => handleSlugChange(e.target.value)}
              onBlur={() => validateField("slug")}
              aria-label={m.tenants_slug_label()}
              aria-invalid={Boolean(errors.slug)}
              data-testid="create-tenant-slug"
              className="
                w-full rounded-base border border-cog-divider
                bg-cog-surface px-cog-2 py-cog-2
                font-mono text-body-sm text-cog-text-primary
                focus:border-cog-blue-600 focus:outline-none
              "
            />
          }
          hint={m.tenants_slug_hint()}
          error={errors.slug}
        />

        {!parentLocked && (
          <Field
            label={m.tenants_parent_tenant_label()}
            input={
              <input
                type="text"
                value={parentId}
                onChange={(e) => setParentId(e.target.value)}
                aria-label={m.tenants_parent_tenant_label()}
                data-testid="create-tenant-parent"
                placeholder={m.tenants_parent_tenant_placeholder()}
                className="
                  w-full rounded-base border border-cog-divider
                  bg-cog-surface px-cog-2 py-cog-2
                  font-mono text-body-sm text-cog-text-primary
                  focus:border-cog-blue-600 focus:outline-none
                "
              />
            }
            hint={m.tenants_parent_tenant_hint()}
          />
        )}

        {/* Trial period is an org-only concept. When the modal is opened
            from an organization's Workspaces tab (parentLocked === true),
            we're creating a sub-workspace — hide this field entirely.
            The submit-payload guard below also drops trial_days when
            parentLocked, defense-in-depth against future state leaks. */}
        {!parentLocked && (
          <Field
            label={m.tenants_trial_period_label()}
            input={
              <div
                role="radiogroup"
                aria-label={m.tenants_trial_period_label()}
                data-testid="create-tenant-trial"
                className="flex flex-wrap gap-cog-2"
              >
                {trialOptions.map((opt) => {
                  const selected = trialDays === opt.value;
                  return (
                    <button
                      key={opt.value}
                      type="button"
                      role="radio"
                      aria-checked={selected}
                      onClick={() => setTrialDays(opt.value)}
                      data-testid={`create-tenant-trial-${opt.value}`}
                      className={[
                        "inline-flex h-cog-6 items-center rounded-base border px-cog-3 text-body-sm font-semibold",
                        "transition-colors duration-standard",
                        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-1",
                        selected
                          ? "border-cog-blue-600 bg-cog-blue-50 text-cog-blue-700 dark:bg-cog-blue-950 dark:text-cog-blue-300"
                          : "border-cog-divider bg-cog-surface text-cog-text-primary hover:border-cog-border hover:bg-cog-surface-muted",
                      ].join(" ")}
                    >
                      {opt.label}
                    </button>
                  );
                })}
              </div>
            }
            hint={m.tenants_trial_hint()}
          />
        )}

        {submit.phase === "preview" && (
          <div
            role="status"
            data-testid="create-tenant-preview"
            className="rounded-base border border-cog-info-200 bg-cog-info-50 px-cog-3 py-cog-2 text-body-sm text-cog-info-500 dark:border-cog-info-dark-border dark:bg-cog-info-dark-bg dark:text-cog-info-dark-text"
          >
            {m.tenants_dry_run_success()}{" "}
            <span className="font-semibold">{submit.result.tenant.name}</span>
            {" at "}
            <span className="font-mono">{submit.result.tenant.slug}</span>.
          </div>
        )}

        {submit.phase === "error" && (
          <p
            role="alert"
            data-testid="create-tenant-error"
            className="rounded-base border border-cog-danger-200 bg-cog-danger-50 px-cog-3 py-cog-2 text-body-sm text-cog-danger-600 dark:border-cog-danger-800 dark:bg-cog-danger-950 dark:text-cog-danger-dark"
          >
            {submit.message}
          </p>
        )}
      </form>
    </Modal>
  );
}

function Field({
  label,
  input,
  hint,
  error,
}: {
  label: TranslatedString;
  input: ReactElement;
  hint?: TranslatedString;
  /** Zod-generated validation message — string, not TranslatedString. */
  error?: string;
}): ReactElement {
  useLocale();
  return (
    <div className="flex flex-col gap-cog-1">
      <p className="text-eyebrow uppercase tracking-cog-eyebrow font-bold text-cog-text-tertiary">
        {label}
      </p>
      {input}
      {error && (
        <span role="alert" className="text-body-sm text-cog-danger-500">
          {error}
        </span>
      )}
      {hint && <p className="text-micro text-cog-text-tertiary">{hint}</p>}
    </div>
  );
}


