/**
 * EditTenantModal — Phase 4h.
 *
 * Lean quick-rename modal opened from the workspace list row kebab
 * menu (and any other "quick edit" affordance we add later). Fields:
 *   - Display name
 *   - Slug
 *
 * Deeper edits (status, owner, danger zone) live on the detail page's
 * Settings tab — the modal is intentionally narrow so the list workflow
 * stays fast. Submits via PATCH /admin/tenants/:id and emits the
 * post-image to the parent for cache swap.
 */

import {
  useCallback,
  useEffect,
  useState,
  type FormEvent,
  type ReactElement,
} from "react";
import { z } from "zod";
import {
  displayNameSchema,
  slugSchema,
  fieldErrorsFromZod,
  useFieldErrors,
  type FieldErrors,
} from "@omnicore-platform/platform-chrome";
import { Modal } from "../components/Modal";
import { updateTenant, type AdminTenant } from "../api/tenants";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { useLocale, type TranslatedString } from "@omnicore-platform/platform-chrome";

const editSchema = z.object({
  name: displayNameSchema,
  slug: slugSchema,
});

export interface EditTenantModalProps {
  open: boolean;
  tenant: AdminTenant;
  onClose: () => void;
  onUpdated: (updated: AdminTenant) => void;
}

type SaveState =
  | { phase: "idle" }
  | { phase: "saving" }
  | { phase: "error"; message: string };

export function EditTenantModal({
  open,
  tenant,
  onClose,
  onUpdated,
}: EditTenantModalProps): ReactElement {
  const [name, setName] = useState(tenant.name);
  const [slug, setSlug] = useState(tenant.slug);
  const [save, setSave] = useState<SaveState>({ phase: "idle" });
  const { errors, setErrors, clear } = useFieldErrors();

  useEffect(() => {
    if (!open) return;
    setName(tenant.name);
    setSlug(tenant.slug);
    setSave({ phase: "idle" });
    clear();
  }, [open, tenant.id, tenant.name, tenant.slug, clear]);

  const nameDirty = name !== tenant.name;
  const slugDirty = slug !== tenant.slug;
  const dirty = nameDirty || slugDirty;

  // Validate only dirty fields against the schema; undirty fields keep their
  // existing (server-confirmed) values so they're allowed through.
  const parseResult = editSchema.safeParse({
    name: nameDirty ? name.trim() : tenant.name,
    slug: slugDirty ? slug.trim() : tenant.slug,
  });
  const canSave = dirty && parseResult.success && save.phase !== "saving";

  function validateField(field: "name" | "slug"): void {
    const result = editSchema.safeParse({
      name: nameDirty ? name.trim() : tenant.name,
      slug: slugDirty ? slug.trim() : tenant.slug,
    });
    if (!result.success) {
      const fieldErrors = fieldErrorsFromZod(result.error);
      if (fieldErrors[field] !== undefined) {
        setErrors((prev: FieldErrors) => ({ ...prev, [field]: fieldErrors[field] }));
      } else {
        clear(field);
      }
    } else {
      clear(field);
    }
  }

  const handleSave = useCallback(
    async (e: FormEvent<HTMLFormElement>): Promise<void> => {
      e.preventDefault();
      if (!canSave) return;
      setSave({ phase: "saving" });
      try {
        const params: { name?: string; slug?: string } = {};
        if (nameDirty) params.name = name;
        if (slugDirty) params.slug = slug;
        const updated = await updateTenant(tenant.id, params);
        onUpdated(updated);
        onClose();
      } catch (err: unknown) {
        setSave({
          phase: "error",
          message: err instanceof Error ? err.message : "Save failed",
        });
      }
    },
    [canSave, name, slug, nameDirty, slugDirty, tenant.id, onUpdated, onClose],
  );

  const footer = (
    <>
      <button
        type="button"
        onClick={onClose}
        className="
          inline-flex h-cog-6-5 items-center rounded-base border border-cog-divider
          bg-cog-surface px-cog-3 text-body-sm font-semibold text-cog-text-primary
          transition-colors duration-standard
          hover:border-cog-border hover:bg-cog-surface-muted
          focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-1
        "
      >
        {m.tenants_cancel_btn()}
      </button>
      <button
        type="submit"
        form="edit-tenant-form"
        disabled={!canSave}
        data-testid="edit-tenant-save"
        className="
          inline-flex h-cog-6-5 items-center rounded-base
          border border-cog-blue-600 bg-cog-blue-600 px-cog-3
          text-body-sm font-semibold text-white
          transition-colors duration-standard
          hover:border-cog-blue-700 hover:bg-cog-blue-700
          focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-1
          disabled:cursor-not-allowed disabled:opacity-50
          dark:border-cog-blue-700 dark:bg-cog-blue-700 dark:text-white
        "
      >
        {save.phase === "saving" ? m.workspaces_saving() : "Save"}
      </button>
    </>
  );

  return (
    <Modal
      title={m.tenants_edit_tenant_title({ name: tenant.name })}
      eyebrow={m.tenants_workspace_eyebrow()}
      open={open}
      onClose={onClose}
      footer={footer}
    >
      <form
        id="edit-tenant-form"
        onSubmit={handleSave}
        data-testid="edit-tenant-form"
        className="flex flex-col gap-cog-4"
      >
        <Field
          label={m.tenants_display_name_label()}
          input={
            <input
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              onBlur={() => validateField("name")}
              aria-label={m.admin_common_display_name_aria()}
              aria-invalid={Boolean(errors.name)}
              data-testid="edit-tenant-name"
              // eslint-disable-next-line jsx-a11y/no-autofocus -- Radix dialog already traps focus; this only moves it from the close button to the name field.
              autoFocus
              className="
                w-full rounded-base border border-cog-divider
                bg-cog-surface px-cog-2 py-cog-2
                text-body-sm text-cog-text-primary
                focus:border-cog-blue-600 focus:outline-none
              "
            />
          }
          error={errors.name}
        />

        <Field
          label={m.tenants_slug_label()}
          input={
            <input
              type="text"
              value={slug}
              onChange={(e) => setSlug(e.target.value)}
              onBlur={() => validateField("slug")}
              aria-label={m.admin_common_slug_aria()}
              aria-invalid={Boolean(errors.slug)}
              data-testid="edit-tenant-slug"
              className="
                w-full rounded-base border border-cog-divider
                bg-cog-surface px-cog-2 py-cog-2
                font-mono text-body-sm text-cog-text-primary
                focus:border-cog-blue-600 focus:outline-none
              "
            />
          }
          hint={m.tenants_slug_hint()}
          error={errors.slug}
        />

        {save.phase === "error" && (
          <p
            role="alert"
            data-testid="edit-tenant-error"
            className="rounded-base border border-cog-danger-200 bg-cog-danger-50 px-cog-3 py-cog-2 text-body-sm text-cog-danger-600 dark:border-cog-danger-800 dark:bg-cog-danger-950 dark:text-cog-danger-dark"
          >
            {save.message}
          </p>
        )}
      </form>
    </Modal>
  );
}

function Field({
  label,
  input,
  hint,
  error,
}: {
  label: TranslatedString;
  input: ReactElement;
  hint?: TranslatedString;
  /** Zod-generated validation message — string, not TranslatedString. */
  error?: string;
}): ReactElement {
  useLocale();
  return (
    <div className="flex flex-col gap-cog-1">
      <p className="text-eyebrow uppercase tracking-cog-eyebrow font-bold text-cog-text-tertiary">
        {label}
      </p>
      {input}
      {error && (
        <span role="alert" className="text-body-sm text-cog-danger-500">
          {error}
        </span>
      )}
      {hint && <p className="text-micro text-cog-text-tertiary">{hint}</p>}
    </div>
  );
}


