/**
 * TenantRowMenu — Phase 4h (Radix strangle, Phase 3 migration).
 *
 * Kebab (3-dot) menu rendered at the end of each row in TenantsTable
 * and the OrgWorkspacesTab. Items: Edit (opens EditTenantModal) and
 * Delete (opens DeleteTenantModal). Both fire callbacks; the parent
 * owns modal state.
 *
 * Built on the shared `@omnicore-platform/ui` DropdownMenu (Radix). Radix
 * supplies the portal (escaping TenantsTable's `overflow-hidden` clip),
 * outside-click + Escape dismissal, focus management, and the
 * role="menu"/role="menuitem" + aria-expanded a11y tree natively — so the
 * previous hand-rolled createPortal + getBoundingClientRect positioning +
 * scroll/resize tracking + outside-click/Esc listeners are gone.
 *
 * Click on the kebab does NOT bubble to the row's onClick: `stopPropagation`
 * on the trigger keeps the row click from firing, and a `stopPropagation` on
 * the menu Content guards item clicks (React routes synthetic events through
 * the React tree, so a portalled item would still bubble to the row).
 */

import { useCallback, type ReactElement } from "react";

import { DropdownMenu } from "@omnicore-platform/ui";
import { MoreVertical } from "@omnicore-platform/ui/icons";

import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { useLocale } from "@omnicore-platform/platform-chrome";
import { useSession } from "../lib/useSession";

export interface TenantRowMenuProps {
  /** Used to compose data-testid so each row's menu is uniquely addressable. */
  tenantID: string;
  /** Parent tenant id. Undefined/empty means this is a root (org) row.
   *  Org-tier users may not Edit/Delete root tenants. */
  parentId?: string;
  onEdit: () => void;
  onDelete: () => void;
}

export function TenantRowMenu({
  tenantID,
  parentId,
  onEdit,
  onDelete,
}: TenantRowMenuProps): ReactElement {
  useLocale();
  const sessionState = useSession();
  const tier =
    sessionState.state === "ready" ? sessionState.session.tier : "member";
  // Root tenants (no parent) are locked for org-tier users.
  const isRoot = !parentId;
  const showMutations = tier === "platform" || !isRoot;

  // Radix dismisses the menu on select; the parent owns the modal that the
  // callback opens. `onSelect` is the keyboard- and pointer-correct hook.
  const fire = useCallback(
    (fn: () => void) => () => {
      fn();
    },
    [],
  );

  return (
    <DropdownMenu.Root>
      <DropdownMenu.Trigger asChild>
        <button
          type="button"
          aria-label={m.admin_tenants_workspace_actions_aria()}
          data-testid={`tenant-row-menu-${tenantID}`}
          // Keep the row's onClick from firing alongside the menu toggle.
          onClick={(e) => e.stopPropagation()}
          className="
            inline-flex h-cog-6 w-cog-6 items-center justify-center rounded-base
            text-cog-text-secondary
            transition-colors duration-standard
            hover:bg-cog-surface-muted hover:text-cog-text-primary
            focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-focus focus-visible:ring-offset-1
          "
        >
          <MoreVertical aria-hidden="true" className="h-cog-4 w-cog-4" />
        </button>
      </DropdownMenu.Trigger>

      {showMutations && (
        <DropdownMenu.Content
          align="end"
          sideOffset={4}
          data-testid={`tenant-row-menu-list-${tenantID}`}
          className="w-cog-15 overflow-hidden"
          // Radix portals Content to document.body, but React routes synthetic
          // events through the React tree — so item clicks would still bubble to
          // the row's onClick. Stop them at the menu surface.
          onClick={(e) => e.stopPropagation()}
        >
          <DropdownMenu.Item
            data-testid={`tenant-row-menu-edit-${tenantID}`}
            onSelect={fire(onEdit)}
            className="
              text-cog-text-primary
              data-[highlighted]:bg-cog-surface-muted
            "
          >
            {m.tenants_edit_workspace_eyebrow()}
          </DropdownMenu.Item>
          <DropdownMenu.Item
            data-testid={`tenant-row-menu-delete-${tenantID}`}
            onSelect={fire(onDelete)}
            className="
              text-cog-danger-600
              data-[highlighted]:bg-cog-danger-50
              dark:text-cog-danger-dark dark:data-[highlighted]:bg-cog-danger-950
            "
          >
            {m.tenants_delete_workspace_eyebrow()}
          </DropdownMenu.Item>
        </DropdownMenu.Content>
      )}
    </DropdownMenu.Root>
  );
}



