/**
 * TenantStatusPill — colored pill for the workspace status column.
 * Phase 4f.
 *
 * Active     → green dot (success-500)
 * Trial      → blue dot + "N days left" suffix (info-500)
 * Past due   → amber dot (warning-500)
 * Suspended  → red dot + muted label (danger-500)
 */

import type { ReactElement } from "react";
import type { AdminTenant, TenantStatus } from "../api/tenants";
import * as m from "@omnicore-platform/platform-chrome/paraglide/messages";
import { useLocale } from "@omnicore-platform/platform-chrome";

function statusLabel(status: TenantStatus): string {
  switch (status) {
    case "active":
      return m.tenants_tenant_status_active();
    case "trial":
      return m.tenants_tenant_status_trial();
    case "past_due":
      return m.tenants_tenant_status_past_due();
    case "suspended":
      return m.tenants_tenant_status_suspended();
    case "unspecified":
      return m.tenants_tenant_status_unknown();
  }
}

const STATUS_TONE: Record<TenantStatus, { dot: string; fg: string }> = {
  active: {
    dot: "bg-cog-success-500",
    fg: "text-cog-success-700 dark:text-cog-success-dark",
  },
  trial: {
    dot: "bg-cog-info-500",
    fg: "text-cog-info-500 dark:text-cog-info-dark-text",
  },
  past_due: {
    dot: "bg-cog-warning-500",
    fg: "text-cog-warning-700 dark:text-cog-warning-dark-text",
  },
  suspended: {
    dot: "bg-cog-danger-500",
    fg: "text-cog-danger-600 dark:text-cog-danger-dark",
  },
  unspecified: {
    dot: "bg-cog-text-tertiary",
    fg: "text-cog-text-tertiary",
  },
};

export interface TenantStatusPillProps {
  status: TenantStatus;
  /** When status === "trial", show "N days left". Pulled from the wire's
   *  trial_days_remaining. */
  trialDaysRemaining?: number;
}

export function TenantStatusPill({
  status,
  trialDaysRemaining,
}: TenantStatusPillProps): ReactElement {
  useLocale();
  // Defensive: older API payloads from before Phase 4f don't carry a
  // status. Treat as unspecified rather than crashing the table.
  const normalized: TenantStatus = STATUS_TONE[status] ? status : "unspecified";
  const tone = STATUS_TONE[normalized];
  const label = statusLabel(normalized);
  const showDays = normalized === "trial" && trialDaysRemaining !== undefined;
  return (
    <span
      data-testid="tenant-status-pill"
      data-status={normalized}
      className={[
        "inline-flex items-center gap-cog-1-5 text-micro font-semibold",
        tone.fg,
      ].join(" ")}
    >
      <span
        aria-hidden="true"
        className={[
          "inline-block h-cog-1-5 w-cog-1-5 rounded-pill",
          tone.dot,
        ].join(" ")}
      />
      {label}
      {showDays && (
        <span className="text-cog-text-tertiary font-normal">
          · {trialDaysRemaining} {trialDaysRemaining === 1 ? "day" : "days"} {m.workspaces_days_left_suffix()}
        </span>
      )}
    </span>
  );
}

/** Convenience for the table cell: takes a tenant and renders the pill. */
export function tenantStatusPillFor(t: AdminTenant): ReactElement {
  return (
    <TenantStatusPill
      status={t.status}
      trialDaysRemaining={t.trial_days_remaining}
    />
  );
}


