/**
 * Tree-ordering helpers shared by the workspaces table and the
 * /admin/members sidebar. Phase 4j: extracted from TenantsTable so
 * the sidebar can consume the same shape without importing the
 * full table component.
 */

import type { AdminTenant } from "../api/tenants";

/** A row in the projected, ordered tree. `depth` controls left indent
 *  in the workspace cell. Phase 4h. */
export interface FlatRow {
  tenant: AdminTenant;
  depth: 0 | 1;
}

/** orderTreeRows projects the flat list returned by /admin/tenants
 *  into the org → workspace order documented at the top of TenantsTable.
 *
 *  Rules:
 *  - Root tenants (parent_id is undefined/null) are organizations.
 *  - Children point at their root via parent_id.
 *  - Sort orgs alphabetically by name; under each, sort children
 *    alphabetically by name.
 *  - Orphan children (parent_id points outside the visible set) fall
 *    through into a synthetic "Other workspaces" tail so they remain
 *    discoverable instead of silently disappearing. */
export function orderTreeRows(tenants: readonly AdminTenant[]): FlatRow[] {
  const compareByName = (a: AdminTenant, b: AdminTenant) =>
    a.name.localeCompare(b.name, undefined, { sensitivity: "base" });

  const orgs = tenants.filter((t) => !t.parent_id).slice().sort(compareByName);
  const childrenByParent = new Map<string, AdminTenant[]>();
  for (const t of tenants) {
    if (!t.parent_id) continue;
    const list = childrenByParent.get(t.parent_id) ?? [];
    list.push(t);
    childrenByParent.set(t.parent_id, list);
  }
  for (const list of childrenByParent.values()) {
    list.sort(compareByName);
  }

  const rows: FlatRow[] = [];
  const orgIDs = new Set(orgs.map((o) => o.id));
  for (const org of orgs) {
    rows.push({ tenant: org, depth: 0 });
    for (const child of childrenByParent.get(org.id) ?? []) {
      rows.push({ tenant: child, depth: 1 });
    }
  }

  // Orphans: children whose parent isn't in the visible result set.
  const orphans: AdminTenant[] = [];
  for (const [parentID, list] of childrenByParent) {
    if (orgIDs.has(parentID)) continue;
    orphans.push(...list);
  }
  orphans.sort(compareByName);
  for (const o of orphans) {
    rows.push({ tenant: o, depth: 0 });
  }

  return rows;
}



